import json
import sqlite3
import sys
import re
from typing import Dict, Any, List, Optional

def parse_condition(condition: str) -> str:
    """Convert condition string to a safe Python expression."""
    # Replace len() with len(name) syntax
    condition = re.sub(r'len\(([^)]+)\)', r'len(\1)', condition)
    return condition

def process_rules_file(rules_path: str) -> Dict[str, Any]:
    """Read and parse the rules JSON file."""
    try:
        with open(rules_path, 'r') as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        sys.stderr.write(f'config error: {e}\n')
        sys.exit(1)
    except IOError as e:
        sys.stderr.write(f'config error: {e}\n')
        sys.exit(1)

def execute_query(conn: sqlite3.Connection, table: str, columns: List[str]) -> List[tuple]:
    """Execute a SELECT query with specified columns."""
    try:
        cursor = conn.cursor()
        query = f"SELECT {', '.join(columns)} FROM {table}"
        cursor.execute(query)
        return cursor.fetchall()
    except sqlite3.Error as e:
        sys.stderr.write(f'db error: {e}\n')
        sys.exit(1)

def process_row(row: tuple, columns: List[str], condition: str, row_index: int) -> Optional[Dict[str, Any]]:
    """Process a single row and check if it matches the condition."""
    try:
        # Create a dictionary mapping column names to row values
        row_dict = dict(zip(columns, row))
        # Evaluate the condition
        if eval(condition, {}, row_dict):
            return row_dict
    except Exception as e:
        sys.stderr.write(f'row {row_index}: {str(e).replace("\n", " ")}\n')
    return None

def main():
    if len(sys.argv) != 3:
        sys.stderr.write('usage: rowcheck.py rules.json data.db\n')
        sys.exit(2)

    rules_path = sys.argv[1]
    db_path = sys.argv[2]

    try:
        rules = process_rules_file(rules_path)
        table = rules['table']
        columns = rules['columns']
        condition = parse_condition(rules['condition'])
    except KeyError as e:
        sys.stderr.write(f'config error: missing key {e}\n')
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_path)
        rows = execute_query(conn, table, columns)
        conn.close()
    except Exception as e:
        sys.stderr.write(f'db error: {e}\n')
        sys.exit(1)

    matched_rows = 0
    for row_index, row in enumerate(rows):
        matched_row = process_row(row, columns, condition, row_index)
        if matched_row is not None:
            print(json.dumps(matched_row))

    sys.stderr.write(f'checked {len(rows)} rows, matched {matched_rows} rows\n')

if __name__ == '__main__':
    main()

import json
import sqlite3
import sys
import re

def parse_condition(condition_str):
    # Replace newlines with spaces for consistency
    condition_str = re.sub(r'\n+', ' ', condition_str)
    return condition_str

def process_row(row, columns):
    values = []
    for col in columns:
        if row[col] is None:
            values.append(None)
        else:
            try:
                if isinstance(row[col], (int, float)):
                    values.append(row[col])
                else:
                    values.append(str(row[col]))
            except:
                values.append(None)
    return values

def main():
    if len(sys.argv) != 3:
        print("usage: rowcheck.py rules.json data.db", file=sys.stderr)
        sys.exit(2)

    rules_file = sys.argv[1]
    db_path = sys.argv[2]

    try:
        with open(rules_file, 'r') as f:
            rules = json.load(f)
    except Exception as e:
        print(f"config error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    table = rules.get('table')
    columns = rules.get('columns', [])
    condition = rules.get('condition', '')

    if not table or not isinstance(columns, list) or not condition:
        print("config error: missing required fields", file=sys.stderr)
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(f"SELECT {', '.join(columns)} FROM {table}")
        rows = cursor.fetchall()
    except Exception as e:
        print(f"db error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    matched_rows = 0
    for index, row in enumerate(rows):
        try:
            condition_str = parse_condition(condition)
            values = process_row(row, columns)

            # Bind values to variables for evaluation
            bound_vars = {}
            for i, col in enumerate(columns):
                bound_vars[col] = values[i]

            # Evaluate the condition
            try:
                result = eval(condition_str, {}, bound_vars)
            except Exception as e:
                print(f"row {index}: {str(e).replace('\n', ' ')}", file=sys.stderr)
                continue

            if result:
                matched_rows += 1
                output = {col: val for col, val in zip(columns, values)}
                print(json.dumps(output))
        except Exception as e:
            print(f"row {index}: {str(e).replace('\n', ' ')}", file=sys.stderr)

    print(f"checked {len(rows)} rows, matched {matched_rows} rows", file=sys.stderr)

if __name__ == "__main__":
    main()

import json
import sqlite3
import sys
import argparse
from typing import Any, Dict, List, Optional

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('rules', type=str, help='JSON rules file')
    parser.add_argument('db', type=str, help='SQLite database path')
    return parser.parse_args()

def load_rules(rules_file: str) -> Dict[str, Any]:
    try:
        with open(rules_file, 'r') as f:
            return json.load(f)
    except Exception as e:
        sys.stderr.write(f'config error: {str(e).replace("\n", " ")}\n')
        sys.exit(1)

def execute_query(db_path: str, table: str, columns: List[str], condition: str) -> List[tuple]:
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        query = f"SELECT {', '.join(columns)} FROM {table} WHERE {condition}"
        cursor.execute(query)
        rows = cursor.fetchall()
        conn.close()
        return rows
    except Exception as e:
        sys.stderr.write(f'db error: {str(e).replace("\n", " ")}\n')
        sys.exit(1)

def process_rows(rows: List[tuple], columns: List[str]) -> List[Dict[str, Any]]:
    matched_rows = []
    for index, row in enumerate(rows):
        try:
            row_dict = {col: row[i] for i, col in enumerate(columns)}
            if eval(condition, {}, row_dict):
                matched_rows.append(row_dict)
        except Exception as e:
            sys.stderr.write(f'row {index}: {str(e).replace("\n", " ")}\n')
    return matched_rows

def main():
    args = parse_args()
    rules = load_rules(args.rules)
    table = rules['table']
    columns = rules['columns']
    condition = rules['condition']

    rows = execute_query(args.db, table, columns, condition)
    matched = process_rows(rows, columns)

    for row in matched:
        print(json.dumps(row))

    sys.stderr.write(f'checked {len(rows)} rows, matched {len(matched)} rows\n')

if __name__ == "__main__":
    main()

import json
import sqlite3
import sys
import re

def parse_condition(condition_str):
    # Replace newlines with spaces and ensure proper Python expression syntax
    condition_str = re.sub(r'\s+', ' ', condition_str).strip()
    return condition_str

def evaluate_condition(row, condition_str):
    try:
        # Bind row values to variables by column name
        for col, val in row.items():
            exec(f"{col} = {val!r}", globals())
        return eval(condition_str)
    except Exception as e:
        return str(e).replace('\n', ' ')

def process_rules_file(rules_path):
    try:
        with open(rules_path, 'r') as f:
            rules = json.load(f)
    except Exception as e:
        print(f"config error: {str(e)}", file=sys.stderr)
        sys.exit(1)
    return rules

def process_database(rules, db_path):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        table = rules['table']
        columns = rules['columns']
        condition = rules['condition']

        # Build SQL query
        query = f"SELECT {', '.join(columns)} FROM {table}"
        if condition:
            query += f" WHERE {condition}"

        cursor.execute(query)
        rows = cursor.fetchall()

        # Convert rows to dicts with column names
        result_rows = []
        for row in rows:
            row_dict = dict(zip(columns, row))
            result_rows.append(row_dict)

        return result_rows
    except Exception as e:
        print(f"db error: {str(e)}", file=sys.stderr)
        sys.exit(1)
    finally:
        conn.close()

def main():
    if len(sys.argv) != 3:
        print("usage: rowcheck.py rules.json data.db", file=sys.stderr)
        sys.exit(2)

    rules_path = sys.argv[1]
    db_path = sys.argv[2]

    rules = process_rules_file(rules_path)
    rows = process_database(rules, db_path)

    matched_rows = []
    for index, row in enumerate(rows):
        condition_str = rules['condition']
        try:
            if evaluate_condition(row, condition_str):
                matched_rows.append(row)
        except Exception as e:
            print(f"row {index}: {str(e).replace('\n', ' ')}", file=sys.stderr)

    for row in matched_rows:
        print(json.dumps(row))

    print(f"checked {len(rows)} rows, matched {len(matched_rows)} rows", file=sys.stderr)

if __name__ == "__main__":
    main()
